import os

class FileSizeAnalyzer:
    def __init__(self, directory):
        self.directory = directory
        self.file_sizes = {}

    def analyze(self):
        if not os.path.exists(self.directory):
            raise ValueError(f"The directory {self.directory} does not exist.")

        if not os.path.isdir(self.directory):
            raise ValueError(f"The path {self.directory} is not a directory.")

        self.file_sizes = self._get_file_sizes(self.directory)

    def _get_file_sizes(self, directory):
        file_sizes = {}
        for root, _, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                try:
                    size = os.path.getsize(file_path)
                    file_sizes[file_path] = size
                except OSError as e:
                    print(f"Error getting size for {file_path}: {e}")
        return file_sizes

    def generate_report(self):
        if not self.file_sizes:
            raise ValueError("No file sizes analyzed. Please run the analyze method first.")

        report = sorted(self.file_sizes.items(), key=lambda item: item[1], reverse=True)
        return report

    def display_report(self):
        report = self.generate_report()
        print(f"{'File Path':<100} {'Size (Bytes)':<15}")
        print("=" * 115)
        for file_path, size in report:
            print(f"{file_path:<100} {size:<15}")

if __name__ == "__main__":
    directory_to_analyze = input("Enter the directory to analyze: ")
    analyzer = FileSizeAnalyzer(directory_to_analyze)

    try:
        analyzer.analyze()
        analyzer.display_report()
    except ValueError as e:
        print(e)
