                    'we': 'will have',
                    'they': 'will have'
                }
            }
        }

    def get_conjugation(self, verb, tense):
        try:
            conjugation = self.verbs_db[verb][tense]
            return conjugation
        except KeyError:
            return None

    def display_conjugation(self, verb):
        print(f"Conjugations for '{verb}':")
        for tense in self.verbs_db.get(verb, {}):
            print(f"\n{tense.capitalize()}:")
            for person, form in self.verbs_db[verb][tense].items():
                print(f"{person}: {form}")

    def run(self):
        while True:
            verb = input("Enter a verb (or 'exit' to quit): ").strip().lower()
            if verb == 'exit':
                break
            if verb not in self.verbs_db:
                print("Verb not found. Please try another verb.")
