        if product_name in self.inventory:
            self.inventory[product_name]['quantity'] += quantity
        else:
            self.inventory[product_name] = {'price': price, 'quantity': quantity}
        print(f"Added {quantity} of {product_name} at ${price} each.")

    def sell_product(self, product_name, quantity):
        if product_name in self.inventory and self.inventory[product_name]['quantity'] >= quantity:
            total_price = self.inventory[product_name]['price'] * quantity
            self.inventory[product_name]['quantity'] -= quantity
            self.balance += total_price
            self.sales += total_price
            print(f"Sold {quantity} of {product_name} for ${total_price}.")
        else:
            print(f"Cannot sell {quantity} of {product_name}. Not enough stock or product does not exist.")

    def display_inventory(self):
        print("Current Inventory:")
        for product, details in self.inventory.items():
            print(f"{product}: ${details['price']} each, {details['quantity']} in stock")

    def get_financial_summary(self):
        return {
            "balance": self.balance,
            "sales": self.sales,
            "inventory": self.inventory
        }

def main():
    store_name = input("Enter your store name: ")
    store = RetailStore(store_name)

    while True:
